CREATE TABLE IF NOT EXISTS public.pulse_surveys(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),organization_id UUID NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,title TEXT NOT NULL,description TEXT,anonymous BOOLEAN NOT NULL DEFAULT TRUE,status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN('draft','published','closed')),created_by UUID REFERENCES public.users(id) ON DELETE SET NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());CREATE TABLE IF NOT EXISTS public.pulse_questions(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),organization_id UUID NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,survey_id UUID NOT NULL REFERENCES public.pulse_surveys(id) ON DELETE CASCADE,prompt TEXT NOT NULL,question_type TEXT NOT NULL DEFAULT 'scale' CHECK(question_type IN('scale','text','multiple_choice','enps')),choices JSONB NOT NULL DEFAULT '[]'::jsonb,sort_order SMALLINT NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT now());CREATE TABLE IF NOT EXISTS public.pulse_responses(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),organization_id UUID NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,survey_id UUID NOT NULL REFERENCES public.pulse_surveys(id) ON DELETE CASCADE,employee_id UUID REFERENCES public.employees(id) ON DELETE SET NULL,anonymous_token_hash TEXT,answers JSONB NOT NULL DEFAULT '{}'::jsonb,submitted_at TIMESTAMPTZ NOT NULL DEFAULT now());ALTER TABLE public.pulse_surveys ENABLE ROW LEVEL SECURITY;ALTER TABLE public.pulse_questions ENABLE ROW LEVEL SECURITY;ALTER TABLE public.pulse_responses ENABLE ROW LEVEL SECURITY;CREATE POLICY tenant_isolation ON public.pulse_surveys FOR ALL USING(public.is_organization_member(organization_id)) WITH CHECK(public.is_organization_member(organization_id));CREATE POLICY tenant_isolation ON public.pulse_questions FOR ALL USING(public.is_organization_member(organization_id)) WITH CHECK(public.is_organization_member(organization_id));CREATE POLICY tenant_isolation ON public.pulse_responses FOR ALL USING(public.is_organization_member(organization_id)) WITH CHECK(public.is_organization_member(organization_id));